//The code was all written by the AI grand model deepseek-r1







// 森林场景 - 光线步进渲染 by Claude
#define MAX_STEPS 128
#define MAX_DIST 100.0
#define SURF_DIST 0.001

mat2 rot(float a) { return mat2(cos(a),-sin(a),sin(a),cos(a)); }

// 噪声函数
float hash(vec2 p) { return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5); }
float noise(vec2 p) {
    vec2 i = floor(p), f = fract(p);
    f *= f*(3.0-2.0*f);
    return mix(mix(hash(i+vec2(0,0)), hash(i+vec2(1,0)),f.x),
               mix(hash(i+vec2(0,1)), hash(i+vec2(1,1)),f.x), f.y);
}

// 地面高度场
float groundHeight(vec2 p) {
    return 0.5*sin(p.x*0.3)*sin(p.y*0.4) + 0.3*noise(p*2.0);
}

// 树干SDF（带树皮细节）
float tree(vec3 p, vec3 pos) {
    vec3 q = p - pos;
    q.xz *= rot(0.5*sin(pos.x*10.0)); // 随机旋转
    float trunk = length(q.xz) - 0.3*(1.0-smoothstep(0.0,5.0,q.y)); // 锥形树干
    trunk = min(trunk, length(q-vec3(0,3.5,0)) - 1.5); // 树冠球体
    trunk -= 0.05*sin(30.0*q.x)*sin(30.0*q.z); // 树皮细节
    return trunk;
}

// 主场景SDF
float scene(vec3 p) {
    // 地面
    float d = p.y - groundHeight(p.xz);

    // 生成树木
    vec2 grid = floor(p.xz/4.0)*4.0;
    for(float x=-2.0; x<=2.0; x+=2.0)
    for(float z=-2.0; z<=2.0; z+=2.0) {
        vec2 pos = grid + vec2(x,z) + 1.0;
        float h = groundHeight(pos);
        if(noise(pos*10.0) > 0.6) { // 随机放置
            d = min(d, tree(p, vec3(pos.x, h, pos.y)));
        }
    }

    return d;
}

// 法线计算
vec3 normal(vec3 p) {
    float d = scene(p);
    vec2 e = vec2(0.01, 0);
    return normalize(d - vec3(
        scene(p-e.xyy), scene(p-e.yxy), scene(p-e.yyx)));
}

// 光线步进
float raymarch(vec3 ro, vec3 rd) {
    float t = 0.0;
    for(int i=0; i<MAX_STEPS; i++) {
        vec3 p = ro + rd*t;
        float d = scene(p);
        if(d < SURF_DIST || t > MAX_DIST) break;
        t += d*0.8; // 加速步进
    }
    return t;
}

// 光照计算
vec3 lighting(vec3 p, vec3 rd) {
    vec3 n = normal(p);
    vec3 lightPos = vec3(10,15,10);
    vec3 l = normalize(lightPos - p);

    // 基础颜色
    vec3 col = mix(vec3(0.3,0.7,0.2), vec3(0.6,0.3,0.1), 
                  smoothstep(0.2,0.8,length(p.xz - floor(p.xz/4.0)*4.0))); // 草地

    if(p.y > groundHeight(p.xz)+2.5) // 树冠
        col = mix(vec3(0.1,0.4,0.1), vec3(0.3,0.6,0.3), noise(p.xz*3.0));

    // 阴影
    float shadow = step(raymarch(p+n*0.1, l), length(lightPos-p));

    // 光照模型
    float diff = max(dot(n,l),0.0);
    float ao = 0.5 + 0.5*n.y; // 环境遮蔽
    float fog = exp(-0.05*length(p)); // 雾效

    return (col*diff*shadow + col*0.3*ao) * fog;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5*iResolution.xy)/iResolution.y;

    // 相机动画
    float time = iTime*0.3;
    vec3 ro = vec3(10.0*sin(time),5.0,10.0*cos(time));
    vec3 lookat = vec3(0,3,0);
    vec3 rd = normalize(vec3(uv, -1.5));
    rd.yz *= rot(-0.3); // 俯角

    // 光线步进
    float t = raymarch(ro, rd);
    vec3 p = ro + rd*t;

    // 着色
    vec3 col = t<MAX_DIST ? lighting(p, rd) : 
              mix(vec3(0.5,0.8,1.0), vec3(1.0), pow(abs(rd.y),3.0)); // 天空

    // 后期处理
    col = pow(col, vec3(0.4545)); // Gamma校正
    fragColor = vec4(col,1.0);
}
